package dev.mixer.android;
import java.util.*;import java.util.function.Consumer;import android.app.Activity;import android.view.View;import android.widget.EditText;import android.view.inputmethod.*;
public final class ProbeOutcomeControls {
 private ProbeOutcomeControls(){}private static int checks;
 private static final class Fatal extends Error{private static final long serialVersionUID=1L;}
 private static void check(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 private static NativeOutcomeProbe.Outcome outcome(List<NativeOutcomeProbe.Outcome> rows,String method){return rows.stream().filter(x->x.method().equals(method)).reduce((a,b)->b).orElseThrow();}
 private static void reset(){ConcreteHostProbe.reset();check(!ConcreteHostProbe.qualificationHookInstalled(),"closed prior qualification hook");}
 public static void main(String[] args){
  Activity a=new Activity();EditText edit=new EditText(a);edit.setText("old");edit.setSelection(3,3);BaseInputConnection target=new BaseInputConnection(edit,true);List<NativeOutcomeProbe.Outcome> rows=new ArrayList<>();
  reset();NativeOutcomeProbe.begin(rows::add);ConcreteHostProbe.hook=(m,p)->{if(m.equals("BaseInputConnection.beginBatchEdit")&&p.equals("beforeReturn"))target.closed=true;};boolean value=target.beginBatchEdit();ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();check(value&&Boolean.TRUE.equals(outcome(rows,"BaseInputConnection.beginBatchEdit").value()),"pre-hook true returned once despite later closed field");check(ConcreteHostProbe.count("BaseInputConnection.beginBatchEdit","entry")==1&&ConcreteHostProbe.count("BaseInputConnection.beginBatchEdit","beforeReturn")==1,"original hook counts");check(NativeOutcomeProbe.clean(),"normal capture clean");
  reset();rows.clear();NativeOutcomeProbe.begin(rows::add);ConcreteHostProbe.hook=(m,p)->{if(m.equals("BaseInputConnection.beginBatchEdit")&&p.equals("beforeReturn"))target.closed=false;};value=target.beginBatchEdit();ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();check(!value&&Boolean.FALSE.equals(outcome(rows,"BaseInputConnection.beginBatchEdit").value()),"pre-hook false not reevaluated");check(NativeOutcomeProbe.clean(),"false clean");
  reset();rows.clear();NativeOutcomeProbe.begin(rows::add);ConcreteHostProbe.hook=(m,p)->{if(m.equals("BaseInputConnection.getTextBeforeCursor")&&p.equals("beforeReturn"))edit.setText("changed");};CharSequence text=target.getTextBeforeCursor(2,0);ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();check(text.toString().equals("ld")&&outcome(rows,"BaseInputConnection.getTextBeforeCursor").value()==text,"exact query object captured before hook changes editor");check(NativeOutcomeProbe.clean(),"query clean");
  reset();rows.clear();NativeOutcomeProbe.begin(rows::add);InputConnection[] expected={null};ConcreteHostProbe.hook=(m,p)->{if(m.equals("EditText.onCreateInputConnection")&&p.equals("beforeReturn")){expected[0]=edit.lastConnection;edit.lastConnection=new BaseInputConnection(edit,true);}};InputConnection created=edit.onCreateInputConnection(new EditorInfo());ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();check(created==expected[0]&&created!=edit.lastConnection&&outcome(rows,"EditText.onCreateInputConnection").value()==created,"creator exact original object result");check(NativeOutcomeProbe.clean(),"creator clean");
  for(boolean fatal:new boolean[]{false,true}){
   reset();rows.clear();Throwable original=fatal?new Fatal():new IllegalStateException("exact ordinary");NativeOutcomeProbe.begin(rows::add);ConcreteHostProbe.hook=(m,p)->{if(m.equals("BaseInputConnection.beginBatchEdit")&&p.equals("beforeReturn")){if(original instanceof Error e)throw e;throw (RuntimeException)original;}};Throwable caught=null;try{target.beginBatchEdit();}catch(RuntimeException|Error f){caught=f;}ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();NativeOutcomeProbe.Outcome observation=outcome(rows,"BaseInputConnection.beginBatchEdit");check(caught==original&&observation.originalException()==original&&observation.completion().equals("exception"),"same original thrown identity");check(rows.stream().noneMatch(o->o.method().equals("BaseInputConnection.beginBatchEdit")&&o.completion().equals("return")),"exception never fabricates return");check(NativeOutcomeProbe.clean(),"exception observation clean");
  }
  reset();rows.clear();List<String> ordering=new ArrayList<>();NativeOutcomeProbe.begin(o->{if(o.method().equals("BaseInputConnection.beginBatchEdit"))ordering.add("outcome");rows.add(o);});ConcreteHostProbe.hook=(m,p)->{if(m.equals("BaseInputConnection.beginBatchEdit")&&p.equals("beforeReturn"))ordering.add("ordinary");};Consumer<ConcreteHostProbe.Event> qualified=e->{if(e.method.equals("BaseInputConnection.beginBatchEdit")&&e.phase.equals("beforeReturn")){check(ConcreteHostProbe.count(e.method,e.phase)==1,"qualification after count");ordering.add("qualification");}};ConcreteHostProbe.installQualificationHook(qualified);check(target.beginBatchEdit(),"qualification normal return");ConcreteHostProbe.clearQualificationHook(qualified);ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();check(ordering.equals(List.of("ordinary","qualification","outcome")),"original hook then qualification then measured outcome");check(NativeOutcomeProbe.clean(),"explicit qualification lifetime clean");
  reset();rows.clear();Fatal evidenceFailure=new Fatal();NativeOutcomeProbe.begin(o->{throw evidenceFailure;});check(target.beginBatchEdit(),"capture failure cannot replace normal original value");NativeOutcomeProbe.end();check(NativeOutcomeProbe.failed()&&!NativeOutcomeProbe.clean()&&NativeOutcomeProbe.captureFailure()==evidenceFailure,"capture failure refuses receipt");
  reset();NativeOutcomeProbe.begin(o->{});Consumer<ConcreteHostProbe.Event> left=e->{};ConcreteHostProbe.installQualificationHook(left);ConcreteHostProbe.reset();check(ConcreteHostProbe.qualificationHookInstalled(),"existing reset semantics separate new lifetime");NativeOutcomeProbe.end();check(!NativeOutcomeProbe.clean(),"unclosed qualification hook refuses");ConcreteHostProbe.clearQualificationHook(left);
  reset();NativeOutcomeProbe.begin(o->{});for(int i=0;i<=NativeOutcomeProbe.LIMIT;i++)check(NativeOutcomeProbe.returned("bound","()Z",target,true),"bound cannot alter value");NativeOutcomeProbe.end();check(NativeOutcomeProbe.failed()&&!NativeOutcomeProbe.clean(),"bounded capture refuses overflow");
  View v=new View(a);reset();rows.clear();NativeOutcomeProbe.begin(rows::add);check(v.requestFocus(),"focus true");check(v.requestFocus(),"focus already true branch");NativeOutcomeProbe.end();check(rows.stream().filter(o->o.method().equals("View.requestFocus")&&Boolean.TRUE.equals(o.value())).count()==2,"both original requestFocus branches observed");check(NativeOutcomeProbe.clean(),"focus branches clean");
  reset();rows.clear();Fatal qualificationFailure=new Fatal();NativeOutcomeProbe.begin(rows::add);Consumer<ConcreteHostProbe.Event> throwing=e->{if(e.method.equals("BaseInputConnection.beginBatchEdit")&&e.phase.equals("beforeReturn"))throw qualificationFailure;};ConcreteHostProbe.installQualificationHook(throwing);Throwable qualificationCaught=null;try{target.beginBatchEdit();}catch(RuntimeException|Error failure){qualificationCaught=failure;}ConcreteHostProbe.clearQualificationHook(throwing);NativeOutcomeProbe.end();check(qualificationCaught==qualificationFailure&&outcome(rows,"BaseInputConnection.beginBatchEdit").originalException()==qualificationFailure,"qualification hook original exception retained and captured");check(ConcreteHostProbe.count("BaseInputConnection.beginBatchEdit","beforeReturn")==1&&NativeOutcomeProbe.clean(),"qualification exception after original count with closed lifetime");
  boolean forbiddenObserverAbsent=false;try{ConcreteHostProbe.class.getDeclaredField("auditSink");}catch(NoSuchFieldException absentField){forbiddenObserverAbsent=true;}check(forbiddenObserverAbsent,"no unguarded pre-count observer exists");
  reset();rows.clear();NativeOutcomeProbe.begin(rows::add);android.os.Handler originalHandler=target.getHandler();NativeOutcomeProbe.end();check(outcome(rows,"BaseInputConnection.getHandler").value()==originalHandler&&NativeOutcomeProbe.clean(),"exact handler construction result captured once without inventing return hook");check(ConcreteHostProbe.count("BaseInputConnection.getHandler","entry")==1&&ConcreteHostProbe.count("BaseInputConnection.getHandler","beforeReturn")==0,"handler original entry-only hook shape retained");
  reset();rows.clear();NativeOutcomeProbe.begin(rows::add);check(target.requestCursorUpdates(0,0),"filtered cursor original boolean");NativeOutcomeProbe.end();check(Boolean.TRUE.equals(outcome(rows,"BaseInputConnection.requestCursorUpdatesFiltered").value())&&outcome(rows,"BaseInputConnection.requestCursorUpdatesFiltered").descriptor().equals("(II)Z")&&NativeOutcomeProbe.clean(),"exact filtered overload outcome");check(ConcreteHostProbe.count("BaseInputConnection.requestCursorUpdatesFiltered","entry")==1&&ConcreteHostProbe.count("BaseInputConnection.requestCursorUpdatesFiltered","beforeReturn")==1,"filtered overload unchanged hit/hook counts");
  System.out.println("PASS passive outcome controls checks="+checks+"; source/leaf host instrumentation only");
 }
}
